import CoreGraphics
import ImageIO
import UniformTypeIdentifiers
import XCTest

final class ClipboardFilterTests: XCTestCase {
    private let plainText = "public.utf8-plain-text"

    func testRejectsPrivacyMarkersAlongsideTextOrImagesInSensitiveMode() {
        for marker in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType",
        ] {
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [plainText, marker], sourceBundleID: nil, securityMode: .sensitive), marker)
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [UTType.png.identifier, marker], sourceBundleID: nil, securityMode: .sensitive), marker)
        }
    }

    func testAllowsPrivacyMarkersPasswordManagersAndFileURLsInNormalMode() {
        for marker in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType",
            "public.file-url",
            "NSFilenamesPboardType",
            "com.apple.pasteboard.promised-file-url",
            "NSFilesPromisePboardType",
        ] {
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [plainText, marker], sourceBundleID: nil, securityMode: .normal), marker)
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [UTType.png.identifier, marker], sourceBundleID: nil, securityMode: .normal), marker)
        }

        for bundleID in [
            "com.1password.1password",
            "com.agilebits.onepassword7",
            "com.apple.keychainaccess",
            "com.apple.Passwords",
            "com.bitwarden.desktop",
            "org.keepassxc.keepassxc",
        ] {
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [plainText], sourceBundleID: bundleID, securityMode: .normal), bundleID)
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [UTType.tiff.identifier], sourceBundleID: bundleID, securityMode: .normal), bundleID)
        }
    }

    func testRejectsKnownPasswordManagersInSensitiveMode() {
        for bundleID in [
            "com.1password.1password",
            "com.agilebits.onepassword7",
            "com.apple.keychainaccess",
            "com.apple.Passwords",
            "com.bitwarden.desktop",
            "org.keepassxc.keepassxc",
        ] {
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [plainText], sourceBundleID: bundleID), bundleID)
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [UTType.tiff.identifier], sourceBundleID: bundleID), bundleID)
        }
    }

    func testRecognizesPasswordManagerInSourceMetadata() {
        XCTAssertTrue(ClipboardFilter.isIgnoredApp(" com.bitwarden.desktop\n"))
        XCTAssertFalse(ClipboardFilter.isIgnoredApp("com.apple.TextEdit"))
        XCTAssertFalse(ClipboardFilter.isIgnoredApp(nil))
    }

    func testAcceptsPlainTextWithKnownOrMissingSource() {
        XCTAssertTrue(ClipboardFilter.shouldRecord(types: [plainText], sourceBundleID: "com.apple.TextEdit"))
        XCTAssertTrue(ClipboardFilter.shouldRecord(types: [plainText], sourceBundleID: nil))
    }

    func testRequiresAdvertisedPlainTextOrSupportedImage() {
        XCTAssertFalse(ClipboardFilter.shouldRecord(types: [], sourceBundleID: nil))
        XCTAssertFalse(ClipboardFilter.shouldRecord(types: ["public.rtf", "public.html"], sourceBundleID: nil))
        XCTAssertFalse(ClipboardFilter.shouldRecord(types: [], sourceBundleID: nil, securityMode: .normal))
    }

    func testAcceptsPlainTextAlongsideRichTextOrWebURL() {
        let types: Set<String> = [plainText, "public.rtf", "public.html", "public.url"]
        XCTAssertTrue(ClipboardFilter.shouldRecord(types: types, sourceBundleID: nil))
    }

    func testRejectsFileURLsEvenWhenTextAndImageAreAvailableInSensitiveMode() {
        for type in [
            "public.file-url", "NSFilenamesPboardType", "com.apple.pasteboard.promised-file-url",
            "NSFilesPromisePboardType",
        ] {
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [plainText, type], sourceBundleID: nil), type)
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [plainText, UTType.png.identifier, type],
                                                        sourceBundleID: nil), type)
        }
    }

    func testRejectsFileURLsInTextWithoutBlockingWebURLs() {
        XCTAssertTrue(ClipboardFilter.containsFileURL("\nFile:///Users/example/image.png"))
        XCTAssertFalse(ClipboardFilter.containsFileURL("https://example.com/image.png"))
    }

    func testAcceptsSupportedImageRepresentationsWithOrWithoutText() {
        for type in [UTType.png, .jpeg, .tiff] {
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [type.identifier], sourceBundleID: nil))
            XCTAssertTrue(ClipboardFilter.shouldRecord(types: [plainText, type.identifier], sourceBundleID: nil))
            XCTAssertTrue(ClipboardFilter.allowsTextFallback(types: [plainText, type.identifier]))
        }
    }

    func testUnsupportedImageTypesStillPreventTextCapture() {
        for type in ["public.image", "public.svg-image", "org.webmproject.webp", "com.compuserve.gif"] {
            XCTAssertFalse(ClipboardFilter.shouldRecord(types: [plainText, type], sourceBundleID: nil), type)
            XCTAssertFalse(ClipboardFilter.allowsTextFallback(types: [plainText, UTType.png.identifier, type]), type)
        }
    }

    func testDetectsCommonTokenAndPrivateKeyShapesInText() {
        let values = [
            "AKIA" + String(repeating: "A", count: 16),
            "ghp_" + String(repeating: "a", count: 36),
            "github_pat_" + String(repeating: "a_", count: 25),
            "xoxb-0000000000-0000000000000-aabbccddeeff",
            "AIza" + String(repeating: "a", count: 35),
            "sk_test_" + String(repeating: "a", count: 24),
            "sk-proj-" + String(repeating: "a_", count: 24),
            "-----BEGIN OPENSSH PRIVATE KEY-----",
            "-----BEGIN ENCRYPTED PRIVATE KEY-----",
            "-----BEGIN PGP PRIVATE KEY BLOCK-----",
        ]
        for (index, value) in values.enumerated() {
            XCTAssertTrue(ClipboardFilter.isSensitive("example=value\nsecret=\"\(value)\""), "Fixture \(index)")
        }
    }

    func testDoesNotFlagOrdinaryTextAndPublicKeyHeaders() {
        XCTAssertFalse(ClipboardFilter.isSensitive("Paste a GitHub token starting with ghp_ or an AWS key starting with AKIA."))
        XCTAssertFalse(ClipboardFilter.isSensitive("-----BEGIN PUBLIC KEY-----\nExample\n-----END PUBLIC KEY-----"))
        XCTAssertFalse(ClipboardFilter.isSensitive("-----BEGIN CERTIFICATE-----"))
    }

    func testNormalizesPNGJPEGAndTIFFToStaticPNG() throws {
        for type in [UTType.png, .jpeg, .tiff] {
            let input = try makeImageData(type, frames: type == .tiff ? 2 : 1)
            let png = try XCTUnwrap(ClipboardFilter.normalizedPNG(from: input, advertisedType: type.identifier))
            let source = try XCTUnwrap(CGImageSourceCreateWithData(png as CFData, nil))
            XCTAssertEqual(CGImageSourceGetType(source) as String?, UTType.png.identifier)
            XCTAssertEqual(CGImageSourceGetCount(source), 1)
            let image = try XCTUnwrap(CGImageSourceCreateImageAtIndex(source, 0, nil))
            XCTAssertEqual(image.width, 12)
            XCTAssertEqual(image.height, 8)
        }
    }

    func testHonorsOrientationAndRemovesSourceMetadata() throws {
        let comment = "Example metadata"
        let input = try makeImageData(.jpeg, properties: [
            kCGImagePropertyOrientation: 6,
            kCGImagePropertyExifDictionary: [kCGImagePropertyExifUserComment: comment],
        ])
        let inputSource = try XCTUnwrap(CGImageSourceCreateWithData(input as CFData, nil))
        let inputProperties = try XCTUnwrap(CGImageSourceCopyPropertiesAtIndex(inputSource, 0, nil) as? [CFString: Any])
        let inputExif = inputProperties[kCGImagePropertyExifDictionary] as? [CFString: Any]
        XCTAssertEqual(inputExif?[kCGImagePropertyExifUserComment] as? String, comment)

        let png = try XCTUnwrap(ClipboardFilter.normalizedPNG(from: input, advertisedType: UTType.jpeg.identifier))
        let source = try XCTUnwrap(CGImageSourceCreateWithData(png as CFData, nil))
        let properties = try XCTUnwrap(CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any])
        XCTAssertEqual(properties[kCGImagePropertyPixelWidth] as? Int, 8)
        XCTAssertEqual(properties[kCGImagePropertyPixelHeight] as? Int, 12)
        let outputExif = properties[kCGImagePropertyExifDictionary] as? [CFString: Any]
        XCTAssertNil(outputExif?[kCGImagePropertyExifUserComment])
    }

    func testRejectsCorruptMismatchedAndUnsupportedImagePayloads() throws {
        let png = try makeImageData(.png)
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: Data("invalid image".utf8), advertisedType: UTType.png.identifier))
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: Data(png.prefix(8)), advertisedType: UTType.png.identifier))
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: png, advertisedType: UTType.jpeg.identifier))
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: png, advertisedType: UTType.gif.identifier))
    }

    func testBoundsInputAndDownsamplesOutput() throws {
        let tooWide = try makeImageData(.png, width: 8_193)
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: tooWide, advertisedType: UTType.png.identifier))
        var tooManyBytes = try makeImageData(.png)
        tooManyBytes.count = ClipboardFilter.maximumImageBytes + 1
        XCTAssertNil(ClipboardFilter.normalizedPNG(from: tooManyBytes, advertisedType: UTType.png.identifier))

        let input = try makeImageData(.png, width: 3_200)
        let png = try XCTUnwrap(ClipboardFilter.normalizedPNG(from: input, advertisedType: UTType.png.identifier))
        let source = try XCTUnwrap(CGImageSourceCreateWithData(png as CFData, nil))
        let image = try XCTUnwrap(CGImageSourceCreateImageAtIndex(source, 0, nil))
        XCTAssertEqual(image.width, 3_072)
    }

    private func makeImageData(_ type: UTType, width: Int = 12, frames: Int = 1,
                               properties: [CFString: Any]? = nil) throws -> Data {
        let bitmap = try XCTUnwrap(CGContext(data: nil, width: width, height: 8, bitsPerComponent: 8,
                                            bytesPerRow: 0, space: CGColorSpaceCreateDeviceRGB(),
                                            bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue))
        bitmap.setFillColor(red: 0.1, green: 0.5, blue: 0.8, alpha: 1)
        bitmap.fill(CGRect(x: 0, y: 0, width: width, height: 8))
        let image = try XCTUnwrap(bitmap.makeImage())
        let data = NSMutableData()
        let destination = try XCTUnwrap(CGImageDestinationCreateWithData(data, type.identifier as CFString, frames, nil))
        for _ in 0..<frames {
            CGImageDestinationAddImage(destination, image, properties as CFDictionary?)
        }
        XCTAssertTrue(CGImageDestinationFinalize(destination))
        return data as Data
    }
}
